def transform(grid):
    # Find the foreground color (the non-3 color in the grid)
    foreground = None
    for row in grid:
        for cell in row:
            if cell != 3:
                foreground = cell
                break
        if foreground:
            break

    if foreground is None:
        return grid

    result = []
    for row in grid:
        has_background = 3 in row
        new_row = []
        for cell in row:
            if has_background and foreground is not None and cell == foreground:
                new_row.append(1)
            else:
                new_row.append(cell)
        result.append(new_row)
    return result
